import sys
sys.path.append('storage/episteme')
from moe_mlp_gater_model import MoE_MLPGater_Net

def _define_hyperparameters():
    # Use the same optimal hyperparameters as the SOTA run for a fair comparison.
    return {
        'learning_rate': 0.001,
        'conv1_features': 32, # High-capacity experts
        'conv2_features': 48,
        'kernel_size': 7,
        'mlp_hidden_size': 64
    }

def create_network(hparams):
    return MoE_MLPGater_Net(
        num_experts=8,
        conv1_features=hparams['conv1_features'],
        conv2_features=hparams['conv2_features'],
        kernel_size=hparams['kernel_size'],
        mlp_hidden_size=hparams['mlp_hidden_size']
    )
